1	use serde::Deserialize;
2	use std::{collections::HashMap, env, fs, path::PathBuf, process::Command};
3	use tg_easy_fs::{BlockDevice, EasyFileSystem};
4	
5	const TARGET_ARCH: &str = "riscv64gc-unknown-none-elf";
6	const BLOCK_SZ: usize = 512;
7	
8	#[derive(Deserialize, Default)]
9	struct Cases {
10	    base: Option<u64>,
11	    step: Option<u64>,
12	    cases: Option<Vec<String>>,
13	}
14	
15	fn main() {
16	    println!("cargo:rerun-if-changed=build.rs");
17	    println!("cargo:rerun-if-env-changed=LOG");
18	    println!("cargo:rerun-if-env-changed=TG_USER_DIR");
19	    println!("cargo:rerun-if-env-changed=TG_USER_VERSION");
20	    println!("cargo:rerun-if-env-changed=TG_USER_CRATE");
21	    println!("cargo:rerun-if-env-changed=TG_USER_LOCAL_DIR");
22	    println!("cargo:rerun-if-env-changed=TG_SKIP_USER_APPS");
23	    println!("cargo:rerun-if-env-changed=CARGO_FEATURE_EXERCISE");
24	
25	    let target_arch = env::var("CARGO_CFG_TARGET_ARCH").unwrap_or_default();
26	
27	    // 只在 RISC-V64 架构上使用链接脚本
28	    if target_arch == "riscv64" {
29	        write_linker();
30	        if should_skip_build_apps() {
31	            return;
32	        }
33	        build_apps_and_pack_fs();
34	    }
35	}
36	
37	fn should_skip_build_apps() -> bool {
38	    if env::var_os("TG_SKIP_USER_APPS").is_some() {
39	        return true;
40	    }
41	
42	    is_packaged_build()
43	}
