66	fn build_apps_and_pack_fs() {
67	    let tg_user_root = ensure_tg_user();
68	    let cases_path = tg_user_root.join("cases.toml");
69	    println!("cargo:rerun-if-changed={}", cases_path.display());
70	    println!(
71	        "cargo:rerun-if-changed={}",
72	        tg_user_root.join("Cargo.toml").display()
73	    );
74	    println!("cargo:rerun-if-changed={}", tg_user_root.join("src").display());
75	
76	    let cfg = fs::read_to_string(&cases_path).unwrap_or_else(|err| {
77	        panic!("failed to read cases.toml from {}: {}", cases_path.display(), err)
78	    });
79	    let mut cases_map: HashMap<String, Cases> = toml::from_str(&cfg).unwrap_or_else(|err| {
80	        panic!("failed to parse cases.toml: {err}")
81	    });
82	
83	    let case_key = if env::var("CARGO_FEATURE_EXERCISE").is_ok() {
84	        "ch8_exercise"
85	    } else {
86	        "ch8"
87	    };
88	    let cases = cases_map.remove(case_key).unwrap_or_default();
89	    let base = cases.base.unwrap_or(0);
90	    let step = cases.step.unwrap_or(0);
91	    let names = cases.cases.unwrap_or_default();
92	
93	    if names.is_empty() {
94	        panic!("no user cases found for {case_key} in {}", cases_path.display());
95	    }
96	
97	    let manifest_dir = PathBuf::from(env::var_os("CARGO_MANIFEST_DIR").unwrap());
98	    let fs_target_dir = manifest_dir
99	        .join("target")
100	        .join(TARGET_ARCH)
101	        .join("debug");
102	    let app_target_dir = tg_user_root
103	        .join("target")
104	        .join(TARGET_ARCH)
105	        .join("debug");
106	
107	    for (i, name) in names.iter().enumerate() {
108	        let base_address = base + i as u64 * step;
109	        build_user_app(&tg_user_root, name, base_address);
110	    }
111	
112	    easy_fs_pack(&names, &app_target_dir, &fs_target_dir).unwrap_or_else(|err| {
113	        panic!(
114	            "failed to pack easy-fs image in {}: {err}",
115	            fs_target_dir.display()
116	        )
117	    });
118	}
