120	fn build_user_app(tg_user_root: &PathBuf, name: &str, base_address: u64) {
121	    let mut cmd = Command::new("cargo");
122	    cmd.args([
123	        "build",
124	        "--manifest-path",
125	        tg_user_root.join("Cargo.toml").to_string_lossy().as_ref(),
126	        "--bin",
127	        name,
128	        "--target",
129	        TARGET_ARCH,
130	    ]);
131	
132	    if base_address != 0 {
133	        cmd.env("BASE_ADDRESS", base_address.to_string());
134	    }
135	
136	    let status = cmd.status().expect("failed to execute cargo build for user app");
137	    if !status.success() {
138	        panic!("failed to build user app {name}");
139	    }
140	}
