142	struct BlockFile(std::sync::Mutex<std::fs::File>);
143	
144	impl BlockDevice for BlockFile {
145	    fn read_block(&self, block_id: usize, buf: &mut [u8]) {
146	        use std::io::{Read, Seek, SeekFrom};
147	        let mut file = self.0.lock().unwrap();
148	        file.seek(SeekFrom::Start((block_id * BLOCK_SZ) as u64))
149	            .expect("Error when seeking!");
150	        assert_eq!(file.read(buf).unwrap(), BLOCK_SZ, "Not a complete block!");
151	    }
152	
153	    fn write_block(&self, block_id: usize, buf: &[u8]) {
154	        use std::io::{Seek, SeekFrom, Write};
155	        let mut file = self.0.lock().unwrap();
156	        file.seek(SeekFrom::Start((block_id * BLOCK_SZ) as u64))
157	            .expect("Error when seeking!");
158	        assert_eq!(file.write(buf).unwrap(), BLOCK_SZ, "Not a complete block!");
159	    }
160	}
161	
162	fn easy_fs_pack(
163	    cases: &[String],
164	    app_target: &PathBuf,
165	    fs_target: &PathBuf,
166	) -> std::io::Result<()> {
167	    use std::fs::OpenOptions;
168	    use std::io::Read;
169	    use std::sync::Arc;
170	
171	    fs::create_dir_all(fs_target)?;
172	    let fs_file = fs_target.join("fs.img");
173	    println!("cargo:rerun-if-changed={}", fs_file.display());
174	    let block_file = Arc::new(BlockFile(std::sync::Mutex::new({
175	        let f = OpenOptions::new()
176	            .read(true)
177	            .write(true)
178	            .create(true)
179	            .open(fs_file)?;
180	        f.set_len(64 * 2048 * BLOCK_SZ as u64).unwrap();
181	        f
182	    })));
183	
184	    let efs = EasyFileSystem::create(block_file, 64 * 2048, 1);
185	    let root_inode = Arc::new(EasyFileSystem::root_inode(&efs));
186	
187	    for case in cases {
188	        let mut host_file = std::fs::File::open(app_target.join(case)).unwrap();
189	        let mut all_data: Vec<u8> = Vec::new();
190	        host_file.read_to_end(&mut all_data).unwrap();
191	        let inode = root_inode.create(case.as_str()).unwrap();
192	        inode.write_at(0, all_data.as_slice());
193	    }
194	
195	    Ok(())
196	}
