117	unsafe extern "C" fn _start() -> ! {
118	    const STACK_SIZE: usize = 32 * 4096;
119	    #[unsafe(link_section = ".boot.stack")]
120	    static mut STACK: [u8; STACK_SIZE] = [0u8; STACK_SIZE];
