165	/// 内核主函数
166	///
167	/// 与第七章相比：
168	/// - 新增 `init_thread`（线程系统调用）和 `init_sync_mutex`（同步原语系统调用）
169	/// - 使用 `PThreadManager`（双层管理器）替代 `PManager`
170	/// - 初始化时同时创建 Process 和 Thread
171	/// - 主循环中新增**线程阻塞**处理（SEMAPHORE_DOWN/MUTEX_LOCK/CONDVAR_WAIT）
172	extern "C" fn rust_main() -> ! {
173	    let layout = tg_linker::KernelLayout::locate();
174	    // 步骤 1：BSS 清零
175	    unsafe { layout.zero_bss() };
176	    // 步骤 2：控制台和日志
177	    tg_console::init_console(&Console);
178	    tg_console::set_log_level(option_env!("LOG"));
179	    tg_console::test_log();
180	    // 步骤 3：堆分配器
181	    tg_kernel_alloc::init(layout.start() as _);
182	    unsafe {
183	        tg_kernel_alloc::transfer(core::slice::from_raw_parts_mut(
184	            layout.end() as _,
185	            MEMORY - layout.len(),
186	        ))
187	    };
188	    // 步骤 4：异界传送门
189	    let portal_size = MultislotPortal::calculate_size(1);
190	    let portal_layout = Layout::from_size_align(portal_size, 1 << Sv39::PAGE_BITS).unwrap();
191	    let portal_ptr = unsafe { alloc(portal_layout) };
192	    assert!(portal_layout.size() < 1 << Sv39::PAGE_BITS);
193	    // 步骤 5：内核地址空间
194	    kernel_space(layout, MEMORY, portal_ptr as _);
195	    // 步骤 6：异界传送门初始化
196	    let portal = unsafe { MultislotPortal::init_transit(PROTAL_TRANSIT.base().val(), 1) };
197	    // 步骤 7：系统调用初始化
198	    tg_syscall::init_io(&SyscallContext);
199	    tg_syscall::init_process(&SyscallContext);
200	    tg_syscall::init_scheduling(&SyscallContext);
201	    tg_syscall::init_clock(&SyscallContext);
202	    tg_syscall::init_signal(&SyscallContext);
203	    tg_syscall::init_thread(&SyscallContext);       // 本章新增：线程系统调用
204	    tg_syscall::init_sync_mutex(&SyscallContext);   // 本章新增：同步原语系统调用
205	    // 步骤 8：加载 initproc（返回 Process + Thread）
206	    let initproc = read_all(FS.open("initproc", OpenFlags::RDONLY).unwrap());
207	    if let Some((process, thread)) = Process::from_elf(ElfFile::new(initproc.as_slice()).unwrap()) {
208	        // 初始化双层管理器：ProcManager（进程）+ ThreadManager（线程）
209	        PROCESSOR.get_mut().set_proc_manager(ProcManager::new());
210	        PROCESSOR.get_mut().set_manager(ThreadManager::new());
211	        let (pid, tid) = (process.pid, thread.tid);
212	        PROCESSOR
213	            .get_mut()
214	            .add_proc(pid, process, ProcId::from_usize(usize::MAX));
215	        PROCESSOR.get_mut().add(tid, thread, pid);
216	    }
217	
218	    // ─── 主调度循环 ───
219	    loop {
220	        let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
221	        if let Some(task) = unsafe { (*processor).find_next() } {
222	            unsafe { task.context.execute(portal, ()) };
223	
224	            match scause::read().cause() {
225	                // ─── 系统调用 ───
226	                scause::Trap::Exception(scause::Exception::UserEnvCall) => {
227	                    use tg_syscall::{SyscallId as Id, SyscallResult as Ret};
228	                    let ctx = &mut task.context.context;
229	                    ctx.move_next();
230	                    let id: Id = ctx.a(7).into();
231	                    let args = [ctx.a(0), ctx.a(1), ctx.a(2), ctx.a(3), ctx.a(4), ctx.a(5)];
232	                    let syscall_ret = tg_syscall::handle(Caller { entity: 0, flow: 0 }, id, args);
233	
234	                    // ─── 信号处理 ───
235	                    let current_proc = unsafe { (*processor).get_current_proc().unwrap() };
236	                    match current_proc.signal.handle_signals(ctx) {
237	                        SignalResult::ProcessKilled(exit_code) => unsafe {
238	                            (*processor).make_current_exited(exit_code as _)
239	                        },
240	                        _ => match syscall_ret {
241	                            Ret::Done(ret) => match id {
242	                                Id::EXIT => unsafe { (*processor).make_current_exited(ret) },
243	                                // ─── 本章新增：同步原语阻塞处理 ───
244	                                // 当 semaphore_down / mutex_lock / condvar_wait 返回 -1 时，
245	                                // 表示资源不可用，将当前线程标记为阻塞态
246	                                Id::SEMAPHORE_DOWN | Id::MUTEX_LOCK | Id::CONDVAR_WAIT => {
247	                                    let ctx = &mut task.context.context;
248	                                    *ctx.a_mut(0) = ret as _;
249	                                    if ret == -1 {
250	                                        // 阻塞：从就绪队列移除，等待资源释放后唤醒
251	                                        unsafe { (*processor).make_current_blocked() };
252	                                    } else {
253	                                        // 成功获取：正常挂起（时间片轮转）
254	                                        unsafe { (*processor).make_current_suspend() };
255	                                    }
256	                                }
257	                                _ => {
258	                                    let ctx = &mut task.context.context;
259	                                    *ctx.a_mut(0) = ret as _;
260	                                    unsafe { (*processor).make_current_suspend() };
261	                                }
262	                            },
263	                            Ret::Unsupported(_) => {
264	                                log::info!("id = {id:?}");
265	                                unsafe { (*processor).make_current_exited(-2) };
266	                            }
267	                        },
268	                    }
269	                }
270	                e => {
271	                    log::error!("unsupported trap: {e:?}");
272	                    unsafe { (*processor).make_current_exited(-3) };
273	                }
274	            }
275	        } else {
276	            println!("no task");
277	            break;
278	        }
279	    }
280	
281	    tg_sbi::shutdown(false)
282	}
