435	    /// IO 系统调用（与第七章基本相同）
436	    ///
437	    /// 注意：本章通过 `get_current_proc()` 获取当前线程所属的进程，
438	    /// 而非直接 `current()`，因为 fd_table 属于进程而非线程。
439	    impl IO for SyscallContext {
440	        fn write(&self, _caller: Caller, fd: usize, buf: usize, count: usize) -> isize {
441	            let current = PROCESSOR.get_mut().get_current_proc().unwrap();
442	            if let Some(ptr) = current.address_space.translate(VAddr::new(buf), READABLE) {
443	                if fd == STDOUT || fd == STDDEBUG {
444	                    print!("{}", unsafe {
445	                        core::str::from_utf8_unchecked(core::slice::from_raw_parts(
446	                            ptr.as_ptr(), count,
447	                        ))
448	                    });
449	                    count as _
450	                } else if let Some(file) = &current.fd_table[fd] {
451	                    let file = file.lock();
452	                    if file.writable() {
453	                        let mut v: Vec<&'static mut [u8]> = Vec::new();
454	                        unsafe { v.push(core::slice::from_raw_parts_mut(ptr.as_ptr(), count)) };
455	                        file.write(UserBuffer::new(v)) as _
456	                    } else { log::error!("file not writable"); -1 }
457	                } else { log::error!("unsupported fd: {fd}"); -1 }
458	            } else { log::error!("ptr not readable"); -1 }
459	        }
460	
461	        fn read(&self, _caller: Caller, fd: usize, buf: usize, count: usize) -> isize {
462	            let current = PROCESSOR.get_mut().get_current_proc().unwrap();
463	            if let Some(ptr) = current.address_space.translate(VAddr::new(buf), WRITEABLE) {
464	                if fd == STDIN {
465	                    let mut ptr = ptr.as_ptr();
466	                    for _ in 0..count {
467	                        unsafe { *ptr = tg_sbi::console_getchar() as u8; ptr = ptr.add(1); }
468	                    }
469	                    count as _
470	                } else if let Some(file) = &current.fd_table[fd] {
471	                    let file = file.lock();
472	                    if file.readable() {
473	                        let mut v: Vec<&'static mut [u8]> = Vec::new();
474	                        unsafe { v.push(core::slice::from_raw_parts_mut(ptr.as_ptr(), count)) };
475	                        file.read(UserBuffer::new(v)) as _
476	                    } else { log::error!("file not readable"); -1 }
477	                } else { log::error!("unsupported fd: {fd}"); -1 }
478	            } else { log::error!("ptr not writeable"); -1 }
479	        }
480	
481	        fn open(&self, _caller: Caller, path: usize, flags: usize) -> isize {
482	            let current = PROCESSOR.get_mut().get_current_proc().unwrap();
483	            if let Some(ptr) = current.address_space.translate(VAddr::new(path), READABLE) {
484	                let mut string = String::new();
485	                let mut raw_ptr: *mut u8 = ptr.as_ptr();
486	                loop {
487	                    unsafe {
488	                        let ch = *raw_ptr;
489	                        if ch == 0 { break; }
490	                        string.push(ch as char);
491	                        raw_ptr = (raw_ptr as usize + 1) as *mut u8;
492	                    }
493	                }
494	                if let Some(file_handle) =
495	                    FS.open(string.as_str(), OpenFlags::from_bits(flags as u32).unwrap())
496	                {
497	                    let new_fd = current.fd_table.len();
498	                    current.fd_table.push(Some(Mutex::new(Fd::File((*file_handle).clone()))));
499	                    new_fd as isize
500	                } else { -1 }
501	            } else { log::error!("ptr not writeable"); -1 }
502	        }
503	
504	        #[inline]
505	        fn close(&self, _caller: Caller, fd: usize) -> isize {
506	            let current = PROCESSOR.get_mut().get_current_proc().unwrap();
507	            if fd >= current.fd_table.len() || current.fd_table[fd].is_none() { return -1; }
508	            current.fd_table[fd].take();
509	            0
510	        }
511	
512	        /// pipe 系统调用
513	        fn pipe(&self, _caller: Caller, pipe: usize) -> isize {
514	            let current = PROCESSOR.get_mut().get_current_proc().unwrap();
515	            let (read_end, write_end) = make_pipe();
516	            let read_fd = current.fd_table.len();
517	            let write_fd = read_fd + 1;
518	            if let Some(mut ptr) = current.address_space
519	                .translate::<usize>(VAddr::new(pipe), WRITEABLE)
520	            { unsafe { *ptr.as_mut() = read_fd }; } else { return -1; }
521	            if let Some(mut ptr) = current.address_space
522	                .translate::<usize>(VAddr::new(pipe + core::mem::size_of::<usize>()), WRITEABLE)
523	            { unsafe { *ptr.as_mut() = write_fd }; } else { return -1; }
524	            current.fd_table.push(Some(Mutex::new(Fd::PipeRead(read_end))));
525	            current.fd_table.push(Some(Mutex::new(Fd::PipeWrite(write_end))));
526	            0
527	        }
528	    }
