535	        /// fork：创建子进程（返回 Process + Thread）
536	        fn fork(&self, _caller: Caller) -> isize {
537	            let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
538	            let current_proc = unsafe { (*processor).get_current_proc().unwrap() };
539	            let parent_pid = current_proc.pid;
540	            let (proc, mut thread) = current_proc.fork().unwrap();
541	            let pid = proc.pid;
542	            *thread.context.context.a_mut(0) = 0 as _;
543	            unsafe {
544	                (*processor).add_proc(pid, proc, parent_pid);
545	                (*processor).add(thread.tid, thread, pid);
546	            }
547	            pid.get_usize() as isize
548	        }
