571	        fn wait(&self, _caller: Caller, pid: isize, exit_code_ptr: usize) -> isize {
572	            let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
573	            let current = unsafe { (*processor).get_current_proc().unwrap() };
574	            const WRITABLE: VmFlags<Sv39> = build_flags("W_V");
575	            if let Some((dead_pid, exit_code)) =
576	                unsafe { (*processor).wait(ProcId::from_usize(pid as usize)) }
577	            {
578	                if let Some(mut ptr) = current.address_space
579	                    .translate::<i32>(VAddr::new(exit_code_ptr), WRITABLE)
580	                { unsafe { *ptr.as_mut() = exit_code as i32 }; }
581	                return dead_pid.get_usize() as isize;
582	            } else { return -1; }
583	        }
