617	    /// 信号系统调用（与第七章相同）
618	    impl Signal for SyscallContext {
619	        fn kill(&self, _caller: Caller, pid: isize, signum: u8) -> isize {
620	            if let Some(target_task) = PROCESSOR.get_mut()
621	                .get_proc(ProcId::from_usize(pid as usize))
622	            {
623	                if let Ok(signal_no) = SignalNo::try_from(signum) {
624	                    if signal_no != SignalNo::ERR {
625	                        target_task.signal.add_signal(signal_no);
626	                        return 0;
627	                    }
628	                }
629	            }
630	            -1
631	        }
632	
633	        fn sigaction(&self, _caller: Caller, signum: u8, action: usize, old_action: usize) -> isize {
634	            if signum as usize > tg_signal::MAX_SIG { return -1; }
635	            let current = PROCESSOR.get_mut().get_current_proc().unwrap();
636	            if let Ok(signal_no) = SignalNo::try_from(signum) {
637	                if signal_no == SignalNo::ERR { return -1; }
638	                if old_action as usize != 0 {
639	                    if let Some(mut ptr) = current.address_space.translate(VAddr::new(old_action), WRITEABLE) {
640	                        if let Some(signal_action) = current.signal.get_action_ref(signal_no) {
641	                            *unsafe { ptr.as_mut() } = signal_action;
642	                        } else { return -1; }
643	                    } else { return -1; }
644	                }
645	                if action as usize != 0 {
646	                    if let Some(ptr) = current.address_space.translate(VAddr::new(action), READABLE) {
647	                        if !current.signal.set_action(signal_no, &unsafe { *ptr.as_ptr() }) { return -1; }
648	                    } else { return -1; }
649	                }
650	                return 0;
651	            }
652	            -1
653	        }
