659	        fn sigreturn(&self, _caller: Caller) -> isize {
660	            let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
661	            let current = unsafe { (*processor).get_current_proc().unwrap() };
662	            let current_thread = unsafe { (*processor).current().unwrap() };
663	            if current.signal.sig_return(&mut current_thread.context.context) { 0 } else { -1 }
664	        }
665	    }
