717	    /// 同步原语系统调用（**本章新增**）
718	    ///
719	    /// 实现 Mutex、Semaphore、Condvar 的创建和操作。
720	    /// 这些同步原语存储在 Process 的列表中，由所有线程共享。
721	    impl SyncMutex for SyscallContext {
722	        /// 创建信号量（初始计数 = res_count）
723	        fn semaphore_create(&self, _caller: Caller, res_count: usize) -> isize {
724	            let current_proc = PROCESSOR.get_mut().get_current_proc().unwrap();
725	            let id = if let Some(id) = current_proc.semaphore_list.iter().enumerate()
726	                .find(|(_, item)| item.is_none()).map(|(id, _)| id)
727	            {
728	                current_proc.semaphore_list[id] = Some(Arc::new(Semaphore::new(res_count)));
729	                id
730	            } else {
731	                current_proc.semaphore_list.push(Some(Arc::new(Semaphore::new(res_count))));
732	                current_proc.semaphore_list.len() - 1
733	            };
734	            id as isize
735	        }
736	
737	        /// V 操作：释放信号量，唤醒等待线程
738	        fn semaphore_up(&self, _caller: Caller, sem_id: usize) -> isize {
739	            let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
740	            let current_proc = unsafe { (*processor).get_current_proc().unwrap() };
741	            let sem = Arc::clone(current_proc.semaphore_list[sem_id].as_ref().unwrap());
742	
743	            let tid = unsafe { (*processor).current().unwrap().tid.get_usize() };
744	            if let Some(s_list) = current_proc.sem_allocations.get_mut(&tid) {
745	                if let Some(pos) = s_list.iter().position(|&x| x == sem_id) {
746	                    s_list.remove(pos);
747	                }
748	            }
749	
750	            if let Some(waking_tid) = sem.up() {
751	                // 唤醒的线程获得了资源
752	                current_proc.sem_requests.remove(&waking_tid.get_usize());
753	                current_proc.sem_allocations.entry(waking_tid.get_usize()).or_default().push(sem_id);
754	                unsafe { (*processor).re_enque(waking_tid); }
755	            }
756	            0
757	        }
758	
759	        /// P 操作：获取信号量，不可用则阻塞
760	        fn semaphore_down(&self, _caller: Caller, sem_id: usize) -> isize {
761	            let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
762	            let current = unsafe { (*processor).current().unwrap() };
763	            let tid = current.tid;
764	            let current_proc = unsafe { (*processor).get_current_proc().unwrap() };
765	
766	            if current_proc.is_deadlock_detect_enabled {
767	                if crate::deadlock::check_deadlock(tid.get_usize(), None, Some(sem_id), current_proc) {
768	                    return -0xDEAD;
769	                }
770	            }
771	
772	            let sem = Arc::clone(current_proc.semaphore_list[sem_id].as_ref().unwrap());
773	            if !sem.down(tid) {
774	                current_proc.sem_requests.insert(tid.get_usize(), sem_id);
775	                -1
776	            } else {
777	                current_proc.sem_allocations.entry(tid.get_usize()).or_default().push(sem_id);
778	                0
779	            }
780	        }
781	
782	        /// 创建互斥锁（blocking=true 为阻塞锁）
783	        fn mutex_create(&self, _caller: Caller, blocking: bool) -> isize {
784	            let new_mutex: Option<Arc<dyn MutexTrait>> = if blocking {
785	                Some(Arc::new(MutexBlocking::new()))
786	            } else { None };
787	            let current_proc = PROCESSOR.get_mut().get_current_proc().unwrap();
788	            if let Some(id) = current_proc.mutex_list.iter().enumerate()
789	                .find(|(_, item)| item.is_none()).map(|(id, _)| id)
790	            {
791	                current_proc.mutex_list[id] = new_mutex;
792	                id as isize
793	            } else {
794	                current_proc.mutex_list.push(new_mutex);
795	                current_proc.mutex_list.len() as isize - 1
796	            }
797	        }
798	
799	        /// 解锁，唤醒等待线程
800	        fn mutex_unlock(&self, _caller: Caller, mutex_id: usize) -> isize {
801	            let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
802	            let current_proc = unsafe { (*processor).get_current_proc().unwrap() };
803	            let mutex = Arc::clone(current_proc.mutex_list[mutex_id].as_ref().unwrap());
804	
805	            let tid = unsafe { (*processor).current().unwrap().tid.get_usize() };
806	            if let Some(m_list) = current_proc.mutex_allocations.get_mut(&tid) {
807	                if let Some(pos) = m_list.iter().position(|&x| x == mutex_id) {
808	                    m_list.remove(pos);
809	                }
810	            }
811	
812	            if let Some(waking_tid) = mutex.unlock() {
813	                // 唤醒的线程获得了资源
814	                current_proc.mutex_requests.remove(&waking_tid.get_usize());
815	                current_proc.mutex_allocations.entry(waking_tid.get_usize()).or_default().push(mutex_id);
816	                unsafe { (*processor).re_enque(waking_tid); }
817	            }
818	            0
819	        }
820	
821	        /// 加锁，已被占用则阻塞
822	        fn mutex_lock(&self, _caller: Caller, mutex_id: usize) -> isize {
823	            let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
824	            let current = unsafe { (*processor).current().unwrap() };
825	            let tid = current.tid;
826	            let current_proc = unsafe { (*processor).get_current_proc().unwrap() };
827	
828	            if current_proc.is_deadlock_detect_enabled {
829	                if crate::deadlock::check_deadlock(tid.get_usize(), Some(mutex_id), None, current_proc) {
830	                    return -0xDEAD;
831	                }
832	            }
833	
834	            let mutex = Arc::clone(current_proc.mutex_list[mutex_id].as_ref().unwrap());
835	            if !mutex.lock(tid) {
836	                current_proc.mutex_requests.insert(tid.get_usize(), mutex_id);
837	                -1
838	            } else {
839	                current_proc.mutex_allocations.entry(tid.get_usize()).or_default().push(mutex_id);
840	                0
841	            }
842	        }
843	
844	        /// 创建条件变量
845	        fn condvar_create(&self, _caller: Caller, _arg: usize) -> isize {
846	            let current_proc = PROCESSOR.get_mut().get_current_proc().unwrap();
847	            let id = if let Some(id) = current_proc.condvar_list.iter().enumerate()
848	                .find(|(_, item)| item.is_none()).map(|(id, _)| id)
849	            {
850	                current_proc.condvar_list[id] = Some(Arc::new(Condvar::new()));
851	                id
852	            } else {
853	                current_proc.condvar_list.push(Some(Arc::new(Condvar::new())));
854	                current_proc.condvar_list.len() - 1
855	            };
856	            id as isize
857	        }
858	
859	        /// 唤醒一个等待线程
860	        fn condvar_signal(&self, _caller: Caller, condvar_id: usize) -> isize {
861	            let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
862	            let current_proc = unsafe { (*processor).get_current_proc().unwrap() };
863	            let condvar = Arc::clone(current_proc.condvar_list[condvar_id].as_ref().unwrap());
864	            if let Some(tid) = condvar.signal() {
865	                unsafe { (*processor).re_enque(tid); }
866	            }
867	            0
868	        }
869	
870	        /// 等待条件变量（释放锁 + 阻塞 + 重新获取锁）
871	        fn condvar_wait(&self, _caller: Caller, condvar_id: usize, mutex_id: usize) -> isize {
872	            let processor: *mut ProcessorInner = PROCESSOR.get_mut() as *mut ProcessorInner;
873	            let current = unsafe { (*processor).current().unwrap() };
874	            let tid = current.tid;
875	            let current_proc = unsafe { (*processor).get_current_proc().unwrap() };
876	
877	            let tid_usize = tid.get_usize();
878	            if let Some(m_list) = current_proc.mutex_allocations.get_mut(&tid_usize) {
879	                if let Some(pos) = m_list.iter().position(|&x| x == mutex_id) {
880	                    m_list.remove(pos);
881	                }
882	            }
883	
884	            let condvar = Arc::clone(current_proc.condvar_list[condvar_id].as_ref().unwrap());
885	            let mutex = Arc::clone(current_proc.mutex_list[mutex_id].as_ref().unwrap());
886	            let (flag, waking_tid) = condvar.wait_with_mutex(tid, mutex);
887	
888	            if let Some(waking_tid) = waking_tid {
889	                // The waking thread from condvar implicitly tries to acquire the mutex again!
890	                // Since it's done by `wait_with_mutex` inside sync, we might need to be careful here.
891	                // Wait! In tg_sync, `wait_with_mutex` unlocks the mutex and adds tid to condvar wait_queue.
892	                // But it does NOT re-acquire the mutex yet. The user program must call mutex_lock again!
893	                // Let's check `condvar.rs` implementation later. For now, just re-enqueue waking_tid.
894	                unsafe { (*processor).re_enque(waking_tid); }
895	            }
896	            if !flag { -1 } else { 0 }
897	        }
898	
899	        /// 死锁检测
900	        fn enable_deadlock_detect(&self, _caller: Caller, is_enable: i32) -> isize {
901	            let current_proc = PROCESSOR.get_mut().get_current_proc().unwrap();
902	            current_proc.is_deadlock_detect_enabled = is_enable != 0;
903	            0
904	        }
905	    }
906	}
