1	//! 进程与线程管理模块
2	//!
3	//! ## 与第七章的区别
4	//!
5	//! 第七章中 `Process` 既是资源容器又是执行单元。
6	//! 第八章将两者分离：
7	//! - **Process**：资源容器，管理地址空间、文件描述符、**同步原语列表**、信号
8	//! - **Thread**：执行单元，管理 TID 和上下文
9	//!
10	//! 同一进程的所有线程共享 `Process` 中的资源。
11	//!
12	//! ## 新增字段
13	//!
14	//! | 字段 | 说明 |
15	//! |------|------|
16	//! | `semaphore_list` | 信号量列表（进程内所有线程共享） |
17	//! | `mutex_list` | 互斥锁列表 |
18	//! | `condvar_list` | 条件变量列表 |
19	//!
20	//! 教程阅读建议：
21	//!
22	//! - 先看 `Process` 与 `Thread` 的字段分工：明确“资源归进程、执行归线程”；
23	//! - 再看 `fork/exec/from_elf`：理解跨线程模型后，进程复制与替换语义如何变化；
24	//! - 最后结合 `processor.rs` 看线程生命周期与进程资源回收的关系。
25	
26	use crate::{
27	    build_flags, fs::Fd, map_portal, parse_flags, processor::ProcessorInner, Sv39, Sv39Manager,
28	    PROCESSOR,
29	};
30	use alloc::{alloc::alloc_zeroed, boxed::Box, sync::Arc, vec::Vec};
31	use core::alloc::Layout;
32	use spin::Mutex;
33	use tg_kernel_context::{foreign::ForeignContext, LocalContext};
34	use tg_kernel_vm::{
35	    page_table::{MmuMeta, VAddr, PPN, VPN},
36	    AddressSpace,
37	};
38	use tg_signal::Signal;
39	use tg_signal_impl::SignalImpl;
40	use tg_sync::{Condvar, Mutex as MutexTrait, Semaphore};
41	use tg_task_manage::{ProcId, ThreadId};
42	use xmas_elf::{
43	    header::{self, HeaderPt2, Machine},
44	    program, ElfFile,
45	};
46	
47	/// 线程（执行单元）
48	///
49	/// 每个线程有独立的 TID 和上下文（寄存器状态、satp）。
50	/// 同一进程的多个线程共享地址空间。
51	pub struct Thread {
52	    /// 线程 ID（不可变）
53	    pub tid: ThreadId,
54	    /// 执行上下文（包含 LocalContext + satp）
55	    pub context: ForeignContext,
56	}
57	
58	impl Thread {
59	    /// 创建新线程
60	    pub fn new(satp: usize, context: LocalContext) -> Self {
61	        Self {
62	            tid: ThreadId::new(),
63	            context: ForeignContext { context, satp },
64	        }
65	    }
66	}
67	
68	/// 进程（资源容器）
69	///
70	/// 管理地址空间、文件描述符、同步原语、信号等共享资源。
71	/// 一个进程可以包含多个线程。
72	pub struct Process {
73	    /// 进程 ID
74	    pub pid: ProcId,
75	    /// 地址空间（所有线程共享）
76	    pub address_space: AddressSpace<Sv39, Sv39Manager>,
77	    /// 文件描述符表（所有线程共享）
78	    pub fd_table: Vec<Option<Mutex<Fd>>>,
79	    /// 信号处理器
80	    pub signal: Box<dyn Signal>,
81	    /// 信号量列表（**本章新增**，所有线程共享）
82	    pub semaphore_list: Vec<Option<Arc<Semaphore>>>,
83	    /// 互斥锁列表（**本章新增**，所有线程共享）
84	    pub mutex_list: Vec<Option<Arc<dyn MutexTrait>>>,
85	    /// 条件变量列表（**本章新增**，所有线程共享）
86	    pub condvar_list: Vec<Option<Arc<Condvar>>>,
87	    /// 是否开启死锁检测
88	    pub is_deadlock_detect_enabled: bool,
89	    /// 线程已分配的 mutex
90	    pub mutex_allocations: alloc::collections::BTreeMap<usize, Vec<usize>>,
91	    /// 线程已分配的 semaphore
92	    pub sem_allocations: alloc::collections::BTreeMap<usize, Vec<usize>>,
93	    /// 线程正在请求（等待）的 mutex
94	    pub mutex_requests: alloc::collections::BTreeMap<usize, usize>,
95	    /// 线程正在请求（等待）的 semaphore
96	    pub sem_requests: alloc::collections::BTreeMap<usize, usize>,
97	}
