24	/// 全局文件系统实例（延迟初始化）
25	pub static FS: Lazy<FileSystem> = Lazy::new(|| FileSystem {
26	    root: EasyFileSystem::root_inode(&EasyFileSystem::open(BLOCK_DEVICE.clone())),
27	});
28	
29	/// easy-fs 文件系统封装
30	pub struct FileSystem {
31	    /// 根 Inode
32	    root: Inode,
33	}
34	
35	impl FSManager for FileSystem {
36	    /// 打开文件
37	    fn open(&self, path: &str, flags: OpenFlags) -> Option<Arc<FileHandle>> {
38	        let (readable, writable) = flags.read_write();
39	        if flags.contains(OpenFlags::CREATE) {
40	            if let Some(inode) = self.find(path) {
41	                inode.clear();
42	                Some(Arc::new(FileHandle::new(readable, writable, inode)))
43	            } else {
44	                self.root
45	                    .create(path)
46	                    .map(|new_inode| Arc::new(FileHandle::new(readable, writable, new_inode)))
47	            }
48	        } else {
49	            self.find(path).map(|inode| {
50	                if flags.contains(OpenFlags::TRUNC) {
51	                    inode.clear();
52	                }
53	                Arc::new(FileHandle::new(readable, writable, inode))
54	            })
55	        }
56	    }
57	
58	    /// 查找文件
59	    fn find(&self, path: &str) -> Option<Arc<Inode>> {
60	        self.root.find(path)
61	    }
62	
63	    /// 列出目录
64	    fn readdir(&self, _path: &str) -> Option<alloc::vec::Vec<String>> {
65	        Some(self.root.readdir())
66	    }
67	
68	    fn link(&self, _src: &str, _dst: &str) -> isize { unimplemented!() }
69	    fn unlink(&self, _path: &str) -> isize { unimplemented!() }
70	}
71	
72	/// 读取文件全部内容到 Vec<u8>
73	pub fn read_all(fd: Arc<FileHandle>) -> Vec<u8> {
74	    let mut offset = 0usize;
75	    let mut buffer = [0u8; 512];
76	    let mut v: Vec<u8> = Vec::new();
77	    if let Some(inode) = &fd.inode {
78	        loop {
79	            let len = inode.read_at(offset, &mut buffer);
80	            if len == 0 { break; }
81	            offset += len;
82	            v.extend_from_slice(&buffer[..len]);
83	        }
84	    }
85	    v
86	}
87	
88	/// 统一的文件描述符类型
89	///
90	/// 将普通文件、管道读端、管道写端和空描述符统一为一个枚举，
91	/// 简化 `fd_table` 中的类型管理。
92	#[derive(Clone)]
93	pub enum Fd {
94	    /// 普通文件（来自 easy-fs）
95	    File(FileHandle),
96	    /// 管道读端（只读）
97	    PipeRead(PipeReader),
98	    /// 管道写端（只写）
99	    PipeWrite(Arc<PipeWriter>),
100	    /// 空描述符（用于 stdin/stdout/stderr）
101	    Empty {
102	        /// 是否可读
103	        read: bool,
104	        /// 是否可写
105	        write: bool,
106	    },
107	}
108	
109	impl Fd {
110	    /// 该描述符是否可读
111	    pub fn readable(&self) -> bool {
112	        match self {
113	            Fd::File(f) => f.readable(),
114	            Fd::PipeRead(_) => true,
115	            Fd::PipeWrite(_) => false,
116	            Fd::Empty { read, .. } => *read,
117	        }
118	    }
119	
120	    /// 该描述符是否可写
121	    pub fn writable(&self) -> bool {
122	        match self {
123	            Fd::File(f) => f.writable(),
124	            Fd::PipeRead(_) => false,
125	            Fd::PipeWrite(_) => true,
126	            Fd::Empty { write, .. } => *write,
127	        }
128	    }
129	
130	    /// 从描述符读取数据
131	    pub fn read(&self, buf: UserBuffer) -> isize {
132	        match self {
133	            Fd::File(f) => f.read(buf),
134	            Fd::PipeRead(p) => p.read(buf),
135	            _ => -1,
136	        }
137	    }
138	
139	    /// 向描述符写入数据
140	    pub fn write(&self, buf: UserBuffer) -> isize {
141	        match self {
142	            Fd::File(f) => f.write(buf),
143	            Fd::PipeWrite(p) => p.write(buf),
144	            _ => -1,
145	        }
146	    }
147	}
