3	pub fn check_deadlock(
4	    current_tid: usize,
5	    req_mutex: Option<usize>,
6	    req_sem: Option<usize>,
7	    current_proc: &Process
8	) -> bool {
9	    let num_mutexes = current_proc.mutex_list.len();
10	    let num_sems = current_proc.semaphore_list.len();
11	
12	    // Available arrays
13	    let mut available_mutex = alloc::vec![1; num_mutexes];
14	    let mut available_sem = alloc::vec![0; num_sems];
15	
16	    // Compute available mutexes
17	    for (_, m_list) in current_proc.mutex_allocations.iter() {
18	        for &m_id in m_list.iter() {
19	            if m_id < num_mutexes {
20	                available_mutex[m_id] = 0;
21	            }
22	        }
23	    }
24	
25	    // Compute available semaphores
26	    for (i, sem_opt) in current_proc.semaphore_list.iter().enumerate() {
27	        if let Some(sem) = sem_opt {
28	            let count = sem.inner.exclusive_access().count;
29	            available_sem[i] = if count > 0 { count as usize } else { 0 };
30	        }
31	    }
32	
33	    // We need to gather all threads
34	    let mut all_tids = alloc::vec::Vec::new();
35	    for (&tid, _) in current_proc.mutex_allocations.iter() {
36	        if !all_tids.contains(&tid) { all_tids.push(tid); }
37	    }
38	    for (&tid, _) in current_proc.sem_allocations.iter() {
39	        if !all_tids.contains(&tid) { all_tids.push(tid); }
40	    }
41	    for (&tid, _) in current_proc.mutex_requests.iter() {
42	        if !all_tids.contains(&tid) { all_tids.push(tid); }
43	    }
44	    for (&tid, _) in current_proc.sem_requests.iter() {
45	        if !all_tids.contains(&tid) { all_tids.push(tid); }
46	    }
47	    if !all_tids.contains(&current_tid) { all_tids.push(current_tid); }
48	
49	    let n = all_tids.len();
50	    
51	    // Allocation matrices
52	    let mut alloc_m = alloc::vec![alloc::vec![0; num_mutexes]; n];
53	    let mut alloc_s = alloc::vec![alloc::vec![0; num_sems]; n];
54	    // Need matrices (Actually request matrices)
55	    let mut need_m = alloc::vec![alloc::vec![0; num_mutexes]; n];
56	    let mut need_s = alloc::vec![alloc::vec![0; num_sems]; n];
57	
58	    for (idx, &tid) in all_tids.iter().enumerate() {
59	        if let Some(m_list) = current_proc.mutex_allocations.get(&tid) {
60	            for &m_id in m_list.iter() { alloc_m[idx][m_id] += 1; }
61	        }
62	        if let Some(s_list) = current_proc.sem_allocations.get(&tid) {
63	            for &s_id in s_list.iter() { alloc_s[idx][s_id] += 1; }
64	        }
65	        if let Some(&req) = current_proc.mutex_requests.get(&tid) {
66	            need_m[idx][req] += 1;
67	        }
68	        if let Some(&req) = current_proc.sem_requests.get(&tid) {
69	            need_s[idx][req] += 1;
70	        }
71	        
72	        // Add current request
73	        if tid == current_tid {
74	            if let Some(m) = req_mutex { need_m[idx][m] += 1; }
75	            if let Some(s) = req_sem { need_s[idx][s] += 1; }
76	        }
77	    }
78	
79	    let mut work_m = available_mutex.clone();
80	    let mut work_s = available_sem.clone();
81	    let mut finish = alloc::vec![false; n];
82	
83	    loop {
84	        let mut found = false;
85	        for i in 0..n {
86	            if !finish[i] {
87	                // Check if need <= work
88	                let mut can_finish = true;
89	                for j in 0..num_mutexes {
90	                    if need_m[i][j] > work_m[j] { can_finish = false; break; }
91	                }
92	                if can_finish {
93	                    for j in 0..num_sems {
94	                        if need_s[i][j] > work_s[j] { can_finish = false; break; }
95	                    }
96	                }
97	
98	                if can_finish {
99	                    // Reclaim resources
100	                    for j in 0..num_mutexes { work_m[j] += alloc_m[i][j]; }
101	                    for j in 0..num_sems { work_s[j] += alloc_s[i][j]; }
102	                    finish[i] = true;
103	                    found = true;
104	                }
105	            }
106	        }
107	        if !found { break; }
108	    }
109	
110	    // If any is not finished, deadlock
111	    for i in 0..n {
112	        if !finish[i] {
113	            return true; // deadlock!
114	        }
115	    }
116	
117	    false
118	}
