1	//! VirtIO 块设备驱动模块
2	//!
3	//! 通过 MMIO 方式访问 QEMU virt 平台的 VirtIO 块设备，
4	//! 实现 `BlockDevice` trait 以供 easy-fs 使用。
5	//!
6	//! 本模块与第六/七章相同。
7	//!
8	//! 教程阅读建议：
9	//!
10	//! - 本文件在三章里保持稳定，目的是让你把注意力集中到并发语义变化；
11	//! - 建议重点复盘 `virt_to_phys`：它是“驱动可在分页内核中工作”的关键桥接点。
12	
13	use crate::{build_flags, Sv39, KERNEL_SPACE};
14	use alloc::{
15	    alloc::{alloc_zeroed, dealloc},
16	    sync::Arc,
17	};
18	use core::{alloc::Layout, ptr::NonNull};
19	use spin::{Lazy, Mutex};
20	use tg_easy_fs::BlockDevice;
21	use tg_kernel_vm::page_table::{MmuMeta, VAddr, VmFlags};
22	use virtio_drivers::{Hal, MmioTransport, VirtIOBlk, VirtIOHeader};
23	
24	/// VirtIO 设备 MMIO 基地址
25	const VIRTIO0: usize = 0x10001000;
26	
27	/// 全局块设备实例（延迟初始化）
28	pub static BLOCK_DEVICE: Lazy<Arc<dyn BlockDevice>> = Lazy::new(|| {
29	    Arc::new(unsafe {
30	        VirtIOBlock(Mutex::new(
31	            VirtIOBlk::new(
32	                MmioTransport::new(NonNull::new(VIRTIO0 as *mut VirtIOHeader).unwrap())
33	                    .expect("Error when creating MmioTransport"),
34	            )
35	            .expect("Error when creating VirtIOBlk"),
36	        ))
37	    })
38	});
39	
40	/// VirtIO 块设备封装
41	struct VirtIOBlock(Mutex<VirtIOBlk<VirtioHal, MmioTransport>>);
42	
43	// Safety: 内部使用 Mutex 保护，确保线程安全
44	unsafe impl Send for VirtIOBlock {}
45	unsafe impl Sync for VirtIOBlock {}
46	
47	impl BlockDevice for VirtIOBlock {
48	    fn read_block(&self, block_id: usize, buf: &mut [u8]) {
49	        self.0.lock().read_block(block_id, buf)
50	            .expect("Error when reading VirtIOBlk");
51	    }
52	    fn write_block(&self, block_id: usize, buf: &[u8]) {
53	        self.0.lock().write_block(block_id, buf)
54	            .expect("Error when writing VirtIOBlk");
55	    }
56	}
57	
58	/// VirtIO HAL（硬件抽象层）实现
59	struct VirtioHal;
60	
61	impl Hal for VirtioHal {
62	    /// DMA 内存分配
63	    fn dma_alloc(pages: usize) -> usize {
64	        unsafe {
65	            alloc_zeroed(Layout::from_size_align_unchecked(
66	                pages << Sv39::PAGE_BITS, 1 << Sv39::PAGE_BITS,
67	            )) as _
68	        }
69	    }
70	
71	    /// DMA 内存释放
72	    fn dma_dealloc(paddr: usize, pages: usize) -> i32 {
73	        unsafe {
74	            dealloc(
75	                paddr as _,
76	                Layout::from_size_align_unchecked(pages << Sv39::PAGE_BITS, 1 << Sv39::PAGE_BITS),
77	            )
78	        }
79	        0
80	    }
81	
82	    /// 物理地址转虚拟地址（恒等映射）
83	    fn phys_to_virt(paddr: usize) -> usize { paddr }
84	
85	    /// 虚拟地址转物理地址
86	    fn virt_to_phys(vaddr: usize) -> usize {
87	        const VALID: VmFlags<Sv39> = build_flags("__V");
88	        let ptr: NonNull<u8> = unsafe {
89	            KERNEL_SPACE
90	                .assume_init_ref()
91	                .translate(VAddr::new(vaddr), VALID)
92	                .unwrap()
93	        };
94	        ptr.as_ptr() as usize
95	    }
96	}
